    $src = "$base\$f"
    if (Test-Path $src) { Copy-Item $src "$ref\xfa_engine\" -Force; Write-Host "Copied: $f" }
}

# --- 3. PDF RENDERING DLLs ---
$pdfFiles = @("AdobePDFL.dll","pdfldriver.dll","pdfdocument.dll","pdfobjectcache.dll","renderer.dll","designrenderer.dll","softwarerenderer.dll","jfgraphic.dll","jfdom.dll","jftext.dll","jfutility.dll","jfprotocol.dll","jfschema.dll")
